const SHEETS = [
  ['sora-states', ['id', 'state_id', 'state_enum', 'super', 'size', 'vtable', 'ref_reset', 'ref_begin', 'ref_tick', 'ref_end', 'substeps', 'registered_by', 'scope', 'ref_conf', 'note'], STATES],
  ['sora-transitions', ['id', 'from', 'to', 'request', 'gate', 'how', 'ref_addr', 'ref_conf', 'note'], TRANSITIONS],
  ['sora-actions', ['id', 'value', 'unit', 'source', 'evidence', 'ref_addr', 'ref_conf', 'note'], ACTIONS],
];
let bad = 0;
for (const [name, columns, rows] of SHEETS) {
  const ids = new Set(); for (const r of rows) { if (r.length !== columns.length) throw new Error(name + ' row width: ' + r[0]); if (ids.has(r[0])) throw new Error(name + ' duplicate id: ' + r[0]); ids.add(r[0]); }
  const out = JSON.stringify({ sheet: name, group: 'port', columns }).replace(/\}$/, ',"rows":[\n') + rows.map((r) => JSON.stringify(r)).join(',\n') + '\n]}\n';
  const file = path.join(R, 'sheets/port', name + '.json');
  if (process.argv.includes('--check')) { const same = fs.existsSync(file) && fs.readFileSync(file, 'utf8') === out; console.log(same ? name + ': ' + rows.length + ' rows, current' : name + ': sheet differs from tools/sora_actions_sheet.js ' + VERSION); if (!same) bad = 1; continue; }
  fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, out);
  console.log(name + ': ' + rows.length + ' rows written (tools/sora_actions_sheet.js ' + VERSION + ')');
}
process.exit(bad);
